def transform(grid):
    """1 becomes 2 when in a PLUS pattern: Top=1, Bottom=1, Left=0, Right=0"""
    rows = len(grid)
    cols = len(grid[0])
    output = [row[:] for row in grid]

    changes = []
    for r in range(1, rows-1):
        for c in range(1, cols-1):
            if output[r][c] == 1:
                if output[r-1][c] == 1 and output[r+1][c] == 1 and output[r][c-1] == 0 and output[r][c+1] == 0:
                    changes.append((r, c))

    for r, c in changes:
        output[r][c] = 2

    return output


